
// Original fiction. Public themes are recognizable; all dialogue and private scenes are invented.
// v17: full narrative rewrite. All names, events, documents and conflicts are fictional.
const L=s=>{const [id,zh]=s.split('|');if(!id||!zh)throw Error('Missing translation');return{id,zh};};
const O=(label,text,tag)=>({label:L(label),sub:L('Pilih langkahku.|选择我的下一步。'),text:[L(text)],tag:L(tag)});
const D=(key,prompt,...options)=>({key,prompt:L(prompt),options});
const R=[];
function add(title,place,image,quote,intro,first,middle,second,ending){R.push({title:L(title),place:L(place),image,quote:L(quote),intro:intro.map(L),first,middle:middle.map(L),second,ending:ending.map(L),evidence:{id:first.key}});}
function doc(i,title,type,format,items,note,extra={}){R[i].evidence={id:R[i].first.key,title:L(title),type:L(type),format,items:items.map(row=>row.map(L)),note:L(note),...extra};}

